def summarize_orders(orders):
    filtered_orders = [o for o in orders if o["date"].year >= 2024]
    monthly_totals = {}
    for order in filtered_orders:
        month = order["date"].strftime("%Y-%m")
        monthly_totals[month] = monthly_totals.get(month, 0) + order["amount"]
    return monthly_totals

The function now calculates the total order amount grouped by month, excluding orders before 2024.
